PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE studioos_tenant_metadata (
  tenant_id TEXT PRIMARY KEY,
  tenant_key TEXT NOT NULL UNIQUE,
  guild_id TEXT NOT NULL,
  character_id TEXT NOT NULL,
  market TEXT NOT NULL,
  country TEXT NOT NULL,
  locale TEXT NOT NULL,
  schema_version INTEGER NOT NULL DEFAULT 1,
  environment TEXT NOT NULL,
  legacy_tenant_alias TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO "studioos_tenant_metadata" ("tenant_id","tenant_key","guild_id","character_id","market","country","locale","schema_version","environment","legacy_tenant_alias","created_at") VALUES('luna-oracle','luna-oracle','raven-guild','luna','jp','JP','ja-JP',1,'production-preparation','luna-starwind','2026-08-26 01:42:36');
CREATE TABLE studioos_member_context (
  member_id TEXT NOT NULL,
  tenant_id TEXT NOT NULL,
  guild_id TEXT NOT NULL,
  character_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (member_id, tenant_id),
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
CREATE TABLE analytics_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL,
  event_name TEXT NOT NULL,
  event_namespace TEXT NOT NULL,
  path TEXT,
  session_id TEXT,
  member_id TEXT,
  payload_json TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
