CREATE TABLE blog_engine_settings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL UNIQUE,
  enabled INTEGER NOT NULL DEFAULT 1,
  default_author TEXT,
  default_locale TEXT,
  public_base_url TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
INSERT INTO "blog_engine_settings" ("id","tenant_id","enabled","default_author","default_locale","public_base_url","created_at") VALUES(1,'luna-oracle',1,NULL,'ja-JP',NULL,'2026-08-15 19:41:31');
CREATE TABLE blog_engine_articles (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL,
  slug TEXT NOT NULL,
  title TEXT NOT NULL,
  body TEXT,
  locale TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft',
  published_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (tenant_id, slug),
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
INSERT INTO "blog_engine_articles" ("id","tenant_id","slug","title","body","locale","status","published_at","created_at") VALUES(1,'luna-oracle','fukuen-moon-saturn','復縁で月と土星を見る理由｜ルナのホロスコープ読み',replace('## 復縁で月と土星を見る理由を読む前に\n\nうん、ここは少し丁寧に見たいところだよ。占いに慣れている人ほど、ひとつの天体だけで結論を急がないはず。ルナはまずネイタルチャート全体を見て、ASC、MC、ハウス、主要アスペクト、そして相談内容に関係する天体を順番に絞ります。\n\n## 見る天体と判断順\n\n基本は太陽、月、水星、金星、火星、木星、土星です。恋愛なら金星と火星だけでなく、月の安心感、水星の言葉、土星の怖さや時間感覚も見ます。相性ではふたりの金星だけでなく、月同士、水星同士、金星と火星、土星が作る距離を重ねます。\n\n## ハウスとアスペクトの扱い\n\nハウスは、悩みがどの生活領域で起きているかを見る場所です。5ハウスならときめき、7ハウスなら一対一の関係、8ハウスなら深い結びつきや不安、12ハウスなら言えない気持ちとして読みます。アスペクトは主要5種を優先し、オーブが狭いもの、相談テーマに直結するもの、ASC/MCに触れるものを重く見ます。\n\n## 相談内容へ戻す\n\nじゃあ、ここがいちばん大事。星の配置は、相談者を縛るためではなく、今どこで苦しくなっているかを見つける地図です。復縁なら未練と愛情を分ける。相性なら良し悪しで切らず、どこで会話がずれるかを見る。片思いなら動く時期より先に、言葉の温度と距離の詰め方を見る。\n\n## よくある誤読\n\n金星が強いから恋愛運が良い、スクエアがあるから相性が悪い、土星があるから終わり、とは読みません。配置は単独で決めつけず、ハウス、支配星、アスペクト、相談内容を重ねます。ヘビーユーザーほど、この重ね方を見ると鑑定の質が分かります。\n\n## ルナの結論\n\n急がなくて大丈夫。復縁で月と土星を見る理由は、星の名前を並べるだけでは読み切れません。チャートの構造を見て、そこから気持ちの流れを読み、最後に今の相談へ戻す。この順番を守ることで、占いがただの断定ではなく、次の一歩を選ぶための道具になります。','\n',char(10)),'ja-JP','published','2026-08-15 19:41:31','2026-08-15 19:41:31');
INSERT INTO "blog_engine_articles" ("id","tenant_id","slug","title","body","locale","status","published_at","created_at") VALUES(2,'luna-oracle','compatibility-venus','相性で金星だけを見ない理由｜ルナのホロスコープ読み',replace('## 相性で金星だけを見ない理由を読む前に\n\nうん、ここは少し丁寧に見たいところだよ。占いに慣れている人ほど、ひとつの天体だけで結論を急がないはず。ルナはまずネイタルチャート全体を見て、ASC、MC、ハウス、主要アスペクト、そして相談内容に関係する天体を順番に絞ります。\n\n## 見る天体と判断順\n\n基本は太陽、月、水星、金星、火星、木星、土星です。恋愛なら金星と火星だけでなく、月の安心感、水星の言葉、土星の怖さや時間感覚も見ます。相性ではふたりの金星だけでなく、月同士、水星同士、金星と火星、土星が作る距離を重ねます。\n\n## ハウスとアスペクトの扱い\n\nハウスは、悩みがどの生活領域で起きているかを見る場所です。5ハウスならときめき、7ハウスなら一対一の関係、8ハウスなら深い結びつきや不安、12ハウスなら言えない気持ちとして読みます。アスペクトは主要5種を優先し、オーブが狭いもの、相談テーマに直結するもの、ASC/MCに触れるものを重く見ます。\n\n## 相談内容へ戻す\n\nじゃあ、ここがいちばん大事。星の配置は、相談者を縛るためではなく、今どこで苦しくなっているかを見つける地図です。復縁なら未練と愛情を分ける。相性なら良し悪しで切らず、どこで会話がずれるかを見る。片思いなら動く時期より先に、言葉の温度と距離の詰め方を見る。\n\n## よくある誤読\n\n金星が強いから恋愛運が良い、スクエアがあるから相性が悪い、土星があるから終わり、とは読みません。配置は単独で決めつけず、ハウス、支配星、アスペクト、相談内容を重ねます。ヘビーユーザーほど、この重ね方を見ると鑑定の質が分かります。\n\n## ルナの結論\n\n急がなくて大丈夫。相性で金星だけを見ない理由は、星の名前を並べるだけでは読み切れません。チャートの構造を見て、そこから気持ちの流れを読み、最後に今の相談へ戻す。この順番を守ることで、占いがただの断定ではなく、次の一歩を選ぶための道具になります。','\n',char(10)),'ja-JP','published','2026-08-15 19:41:31','2026-08-15 19:41:31');
INSERT INTO "blog_engine_articles" ("id","tenant_id","slug","title","body","locale","status","published_at","created_at") VALUES(3,'luna-oracle','latitude-house','高緯度出生地でハウスを補正する理由｜ルナのホロスコープ読み',replace('## 高緯度出生地でハウスを補正する理由を読む前に\n\nうん、ここは少し丁寧に見たいところだよ。占いに慣れている人ほど、ひとつの天体だけで結論を急がないはず。ルナはまずネイタルチャート全体を見て、ASC、MC、ハウス、主要アスペクト、そして相談内容に関係する天体を順番に絞ります。\n\n## 見る天体と判断順\n\n基本は太陽、月、水星、金星、火星、木星、土星です。恋愛なら金星と火星だけでなく、月の安心感、水星の言葉、土星の怖さや時間感覚も見ます。相性ではふたりの金星だけでなく、月同士、水星同士、金星と火星、土星が作る距離を重ねます。\n\n## ハウスとアスペクトの扱い\n\nハウスは、悩みがどの生活領域で起きているかを見る場所です。5ハウスならときめき、7ハウスなら一対一の関係、8ハウスなら深い結びつきや不安、12ハウスなら言えない気持ちとして読みます。アスペクトは主要5種を優先し、オーブが狭いもの、相談テーマに直結するもの、ASC/MCに触れるものを重く見ます。\n\n## 相談内容へ戻す\n\nじゃあ、ここがいちばん大事。星の配置は、相談者を縛るためではなく、今どこで苦しくなっているかを見つける地図です。復縁なら未練と愛情を分ける。相性なら良し悪しで切らず、どこで会話がずれるかを見る。片思いなら動く時期より先に、言葉の温度と距離の詰め方を見る。\n\n## よくある誤読\n\n金星が強いから恋愛運が良い、スクエアがあるから相性が悪い、土星があるから終わり、とは読みません。配置は単独で決めつけず、ハウス、支配星、アスペクト、相談内容を重ねます。ヘビーユーザーほど、この重ね方を見ると鑑定の質が分かります。\n\n## ルナの結論\n\n急がなくて大丈夫。高緯度出生地でハウスを補正する理由は、星の名前を並べるだけでは読み切れません。チャートの構造を見て、そこから気持ちの流れを読み、最後に今の相談へ戻す。この順番を守ることで、占いがただの断定ではなく、次の一歩を選ぶための道具になります。','\n',char(10)),'ja-JP','published','2026-08-15 19:41:31','2026-08-15 19:41:31');
INSERT INTO "blog_engine_articles" ("id","tenant_id","slug","title","body","locale","status","published_at","created_at") VALUES(4,'luna-oracle','todays-fortune-2026-08-16','今日の占い 2026年8月16日｜ルナの星読み',replace('## 今日の星の空気\n\nうん、今日の空気は「急いで答えを出さず、相手の反応を観察する日」。月は乙女座、金星は山羊座、水星は双子座の流れとして見ています。細かい度数は簡易計算だから断定に使わず、感情、言葉、惹かれ方の温度を見る目印にします。\n\n## 恋愛と相性の流れ\n\n恋愛では、月の安心感と金星の好みを先に見ます。今日は大きな決断より、相手の返事の速さ、言葉の柔らかさ、自分の心がふっと緩む瞬間を拾うほうが向いています。相性は良い悪いで切らず、会話のリズムと距離感を調整してね。\n\n## 仕事と人間関係\n\n水星の流れを見ると、説明を短く整えるほど伝わりやすい日です。言い切るより、確認を挟むほうが味方が増えます。小さな約束を守る、時間を少し早めに見る、そういう地味な動きが運を支えます。\n\n## 12星座へのひとこと\n\n- 牡羊座: 安心できる場所を先に作ると、会話がやわらぎます。\n- 牡牛座: 言葉選びが鍵。軽く見えても本音はちゃんと届きます。\n- 双子座: 気持ちの揺れを隠しすぎず、やさしく出して大丈夫。\n- 蟹座: 魅力が表に出やすい日。見せ方を少しだけ整えて。\n- 獅子座: 細かい確認が信頼につながります。焦らず丁寧に。\n- 乙女座: 相手とのバランスを見直すと、次の動きが見えます。\n- 天秤座: 深読みしすぎたら、事実と想像を分けてみて。\n- 蠍座: 少し外へ意識を向けると、停滞した気分が動きます。\n- 射手座: 現実的な一歩が恋の不安を落ち着かせます。\n- 山羊座: いつもと違う角度の言葉が、空気を軽くします。\n- 水瓶座: やさしさを受け取る練習の日。遠慮しすぎなくて大丈夫。\n- 魚座: 勢いはあるけれど、返事は一拍置くと整います。\n\n## 今日のルナから\n\nラッキーアクションは「身の回りの香りを変える」。今日は派手に運を取りに行くより、心の置き場所を整える日だよ。急がなくて大丈夫。星の流れを味方にして、できることからひとつ選んでいこう。','\n',char(10)),'ja-JP','published','2026-08-15 21:22:15','2026-08-15 21:22:15');
