INSERT INTO "blog_engine_articles" ("id","tenant_id","slug","title","body","locale","status","published_at","created_at") VALUES(22,'luna-oracle','todays-fortune-2026-08-25','今日の占い 2026年8月25日｜ルナの星読み',replace('## 今日の星の空気\n\nうん、今日の空気は「急いで答えを出さず、相手の反応を観察する日」。月は山羊座、金星は山羊座、水星は獅子座の流れとして見ています。細かい度数は簡易計算だから断定に使わず、感情、言葉、惹かれ方の温度を見る目印にします。\n\n## 恋愛と相性の流れ\n\n恋愛では、月の安心感と金星の好みを先に見ます。今日は大きな決断より、相手の返事の速さ、言葉の柔らかさ、自分の心がふっと緩む瞬間を拾うほうが向いています。相性は良い悪いで切らず、会話のリズムと距離感を調整してね。\n\n## 仕事と人間関係\n\n水星の流れを見ると、説明を短く整えるほど伝わりやすい日です。言い切るより、確認を挟むほうが味方が増えます。小さな約束を守る、時間を少し早めに見る、そういう地味な動きが運を支えます。\n\n## 12星座へのひとこと\n\n- 牡羊座: 安心できる場所を先に作ると、会話がやわらぎます。\n- 牡牛座: 言葉選びが鍵。軽く見えても本音はちゃんと届きます。\n- 双子座: 気持ちの揺れを隠しすぎず、やさしく出して大丈夫。\n- 蟹座: 魅力が表に出やすい日。見せ方を少しだけ整えて。\n- 獅子座: 細かい確認が信頼につながります。焦らず丁寧に。\n- 乙女座: 相手とのバランスを見直すと、次の動きが見えます。\n- 天秤座: 深読みしすぎたら、事実と想像を分けてみて。\n- 蠍座: 少し外へ意識を向けると、停滞した気分が動きます。\n- 射手座: 現実的な一歩が恋の不安を落ち着かせます。\n- 山羊座: いつもと違う角度の言葉が、空気を軽くします。\n- 水瓶座: やさしさを受け取る練習の日。遠慮しすぎなくて大丈夫。\n- 魚座: 勢いはあるけれど、返事は一拍置くと整います。\n\n## 今日のルナから\n\nラッキーアクションは「身の回りの香りを変える」。今日は派手に運を取りに行くより、心の置き場所を整える日だよ。急がなくて大丈夫。星の流れを味方にして、できることからひとつ選んでいこう。','\n',char(10)),'ja-JP','published','2026-08-24 22:00:52','2026-08-24 22:00:52');
INSERT INTO "blog_engine_articles" ("id","tenant_id","slug","title","body","locale","status","published_at","created_at") VALUES(23,'luna-oracle','latitude-house-2','高緯度出生地でハウスを補正する理由｜ルナのホロスコープ読み',replace('## 高緯度出生地でハウスを補正する理由を読む前に\n\nうん、ここは少し丁寧に見たいところだよ。占いに慣れている人ほど、ひとつの天体だけで結論を急がないはず。ルナはまずネイタルチャート全体を見て、ASC、MC、ハウス、主要アスペクト、そして相談内容に関係する天体を順番に絞ります。\n\n## 見る天体と判断順\n\n基本は太陽、月、水星、金星、火星、木星、土星です。恋愛なら金星と火星だけでなく、月の安心感、水星の言葉、土星の怖さや時間感覚も見ます。相性ではふたりの金星だけでなく、月同士、水星同士、金星と火星、土星が作る距離を重ねます。\n\n## ハウスとアスペクトの扱い\n\nハウスは、悩みがどの生活領域で起きているかを見る場所です。5ハウスならときめき、7ハウスなら一対一の関係、8ハウスなら深い結びつきや不安、12ハウスなら言えない気持ちとして読みます。アスペクトは主要5種を優先し、オーブが狭いもの、相談テーマに直結するもの、ASC/MCに触れるものを重く見ます。\n\n## 相談内容へ戻す\n\nじゃあ、ここがいちばん大事。星の配置は、相談者を縛るためではなく、今どこで苦しくなっているかを見つける地図です。復縁なら未練と愛情を分ける。相性なら良し悪しで切らず、どこで会話がずれるかを見る。片思いなら動く時期より先に、言葉の温度と距離の詰め方を見る。\n\n## よくある誤読\n\n金星が強いから恋愛運が良い、スクエアがあるから相性が悪い、土星があるから終わり、とは読みません。配置は単独で決めつけず、ハウス、支配星、アスペクト、相談内容を重ねます。ヘビーユーザーほど、この重ね方を見ると鑑定の質が分かります。\n\n## ルナの結論\n\n急がなくて大丈夫。高緯度出生地でハウスを補正する理由は、星の名前を並べるだけでは読み切れません。チャートの構造を見て、そこから気持ちの流れを読み、最後に今の相談へ戻す。この順番を守ることで、占いがただの断定ではなく、次の一歩を選ぶための道具になります。','\n',char(10)),'ja-JP','published','2026-08-25 08:00:52','2026-08-25 04:00:52');
INSERT INTO "blog_engine_articles" ("id","tenant_id","slug","title","body","locale","status","published_at","created_at") VALUES(24,'luna-oracle','todays-fortune-2026-08-26','今日の占い 2026年8月26日｜ルナの星読み',replace('## 今日の星の空気\n\nうん、今日の空気は「気持ちを整えてから言葉を選ぶ日」。月は水瓶座、金星は山羊座、水星は獅子座の流れとして見ています。細かい度数は簡易計算だから断定に使わず、感情、言葉、惹かれ方の温度を見る目印にします。\n\n## 恋愛と相性の流れ\n\n恋愛では、月の安心感と金星の好みを先に見ます。今日は大きな決断より、相手の返事の速さ、言葉の柔らかさ、自分の心がふっと緩む瞬間を拾うほうが向いています。相性は良い悪いで切らず、会話のリズムと距離感を調整してね。\n\n## 仕事と人間関係\n\n水星の流れを見ると、説明を短く整えるほど伝わりやすい日です。言い切るより、確認を挟むほうが味方が増えます。小さな約束を守る、時間を少し早めに見る、そういう地味な動きが運を支えます。\n\n## 12星座へのひとこと\n\n- 牡羊座: 言葉選びが鍵。軽く見えても本音はちゃんと届きます。\n- 牡牛座: 気持ちの揺れを隠しすぎず、やさしく出して大丈夫。\n- 双子座: 魅力が表に出やすい日。見せ方を少しだけ整えて。\n- 蟹座: 細かい確認が信頼につながります。焦らず丁寧に。\n- 獅子座: 相手とのバランスを見直すと、次の動きが見えます。\n- 乙女座: 深読みしすぎたら、事実と想像を分けてみて。\n- 天秤座: 少し外へ意識を向けると、停滞した気分が動きます。\n- 蠍座: 現実的な一歩が恋の不安を落ち着かせます。\n- 射手座: いつもと違う角度の言葉が、空気を軽くします。\n- 山羊座: やさしさを受け取る練習の日。遠慮しすぎなくて大丈夫。\n- 水瓶座: 勢いはあるけれど、返事は一拍置くと整います。\n- 魚座: 安心できる場所を先に作ると、会話がやわらぎます。\n\n## 今日のルナから\n\nラッキーアクションは「気になっていた予定をひとつ整理する」。今日は派手に運を取りに行くより、心の置き場所を整える日だよ。急がなくて大丈夫。星の流れを味方にして、できることからひとつ選んでいこう。','\n',char(10)),'ja-JP','published','2026-08-25 22:00:50','2026-08-25 22:00:50');
INSERT INTO "blog_engine_articles" ("id","tenant_id","slug","title","body","locale","status","published_at","created_at") VALUES(25,'luna-oracle','asc-mc-love-2','ASCとMCを恋愛相談へ戻す読み方｜ルナのホロスコープ読み',replace('## ASCとMCを恋愛相談へ戻す読み方を読む前に\n\nうん、ここは少し丁寧に見たいところだよ。占いに慣れている人ほど、ひとつの天体だけで結論を急がないはず。ルナはまずネイタルチャート全体を見て、ASC、MC、ハウス、主要アスペクト、そして相談内容に関係する天体を順番に絞ります。\n\n## 見る天体と判断順\n\n基本は太陽、月、水星、金星、火星、木星、土星です。恋愛なら金星と火星だけでなく、月の安心感、水星の言葉、土星の怖さや時間感覚も見ます。相性ではふたりの金星だけでなく、月同士、水星同士、金星と火星、土星が作る距離を重ねます。\n\n## ハウスとアスペクトの扱い\n\nハウスは、悩みがどの生活領域で起きているかを見る場所です。5ハウスならときめき、7ハウスなら一対一の関係、8ハウスなら深い結びつきや不安、12ハウスなら言えない気持ちとして読みます。アスペクトは主要5種を優先し、オーブが狭いもの、相談テーマに直結するもの、ASC/MCに触れるものを重く見ます。\n\n## 相談内容へ戻す\n\nじゃあ、ここがいちばん大事。星の配置は、相談者を縛るためではなく、今どこで苦しくなっているかを見つける地図です。復縁なら未練と愛情を分ける。相性なら良し悪しで切らず、どこで会話がずれるかを見る。片思いなら動く時期より先に、言葉の温度と距離の詰め方を見る。\n\n## よくある誤読\n\n金星が強いから恋愛運が良い、スクエアがあるから相性が悪い、土星があるから終わり、とは読みません。配置は単独で決めつけず、ハウス、支配星、アスペクト、相談内容を重ねます。ヘビーユーザーほど、この重ね方を見ると鑑定の質が分かります。\n\n## ルナの結論\n\n急がなくて大丈夫。ASCとMCを恋愛相談へ戻す読み方は、星の名前を並べるだけでは読み切れません。チャートの構造を見て、そこから気持ちの流れを読み、最後に今の相談へ戻す。この順番を守ることで、占いがただの断定ではなく、次の一歩を選ぶための道具になります。','\n',char(10)),'ja-JP','published','2026-08-26 08:00:50','2026-08-26 04:00:52');
CREATE TABLE sns_posts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL,
  provider TEXT,
  external_post_id TEXT,
  status TEXT NOT NULL DEFAULT 'draft',
  locale TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
CREATE TABLE reel_assets (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL,
  storage_namespace TEXT NOT NULL,
  public_url TEXT,
  status TEXT NOT NULL DEFAULT 'draft',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
CREATE TABLE growth_metric_points (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id TEXT NOT NULL,
  metric_name TEXT NOT NULL,
  metric_value REAL,
  observed_at TEXT,
  source TEXT,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
CREATE TABLE growth_evidence_sources (
  source_id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  source_type TEXT NOT NULL,
  provider TEXT,
  source_name TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  retrieved_at TEXT,
  observed_at TEXT,
  quality_score REAL,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
CREATE TABLE growth_evidence_claims (
  claim_id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  source_id TEXT NOT NULL,
  evidence_scope TEXT NOT NULL,
  statement TEXT NOT NULL,
  metric_name TEXT,
  metric_value REAL,
  confidence REAL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id),
  FOREIGN KEY (source_id) REFERENCES growth_evidence_sources(source_id)
);
CREATE TABLE growth_hypotheses (
  hypothesis_id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  observation TEXT NOT NULL,
  hypothesis TEXT NOT NULL,
  confidence REAL,
  status TEXT NOT NULL DEFAULT 'draft',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
CREATE TABLE growth_proposals (
  proposal_id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  hypothesis_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'review_required',
  risk_class TEXT NOT NULL,
  execution_allowed INTEGER NOT NULL DEFAULT 0 CHECK (execution_allowed = 0),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id),
  FOREIGN KEY (hypothesis_id) REFERENCES growth_hypotheses(hypothesis_id)
);
CREATE TABLE growth_experiments (
  experiment_id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  proposal_id TEXT,
  status TEXT NOT NULL DEFAULT 'DRAFT',
  requires_start_approval INTEGER NOT NULL DEFAULT 1 CHECK (requires_start_approval = 1),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
CREATE TABLE growth_knowledge_items (
  knowledge_id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft',
  learning TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
CREATE TABLE growth_memory (
  memory_id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  proposal_id TEXT,
  experiment_id TEXT,
  predicted_value REAL,
  actual_value REAL,
  absolute_error REAL,
  relative_error REAL,
  reusable INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
CREATE TABLE growth_precision_snapshots (
  snapshot_id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  sample_size INTEGER NOT NULL DEFAULT 0,
  calibration_status TEXT NOT NULL DEFAULT 'insufficient_learning',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tenant_id) REFERENCES studioos_tenant_metadata(tenant_id)
);
CREATE TABLE studioos_reading_feedback (import_id INTEGER PRIMARY KEY AUTOINCREMENT, source_id TEXT NOT NULL, source_tenant_id TEXT NOT NULL, tenant_id TEXT NOT NULL, character_id TEXT NOT NULL, theme TEXT, rating INTEGER, comment TEXT, page_path TEXT, created_at TEXT, UNIQUE(source_id, source_tenant_id));
INSERT INTO "studioos_reading_feedback" ("import_id","source_id","source_tenant_id","tenant_id","character_id","theme","rating","comment","page_path","created_at") VALUES(1,'915d7424-994d-44c0-9cdf-b083dbb08deb','luna-starwind','luna-oracle','luna','verification','helpful','','/ai-reading','2026-08-15 14:44:32');
